  1	/* ============================================================
  2	   utils.js — Shared utility functions
  3	   Section 4 of the MCP Server Dashboard SPA
  4	   ============================================================ */
  5	
  6	function escapeHtml(str) {
  7	  if (str === null || str === undefined) return '';
  8	  return String(str)
  9	    .replace(/&/g, '&amp;')
 10	    .replace(/</g, '&lt;')
 11	    .replace(/>/g, '&gt;')
 12	    .replace(/"/g, '&quot;');
 13	}
 14	
 15	function formatDate(isoString) {
 16	  if (!isoString) return '—';
 17	  try {
 18	    var d = new Date(isoString);
 19	    if (isNaN(d.getTime())) return escapeHtml(isoString);
 20	    var pad = function (n) { return String(n).padStart(2, '0'); };
 21	    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes());
 22	
 23	    var now = new Date();
 24	    // Strip times for day-boundary comparisons
 25	    var today    = new Date(now.getFullYear(),    now.getMonth(),    now.getDate());
 26	    var itemDay  = new Date(d.getFullYear(),      d.getMonth(),      d.getDate());
 27	    var diffDays = Math.round((today - itemDay) / 86400000);
 28	
 29	    if (diffDays === 0) return 'Today, ' + timeStr;
 30	    if (diffDays === 1) return 'Yesterday, ' + timeStr;
 31	    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 32	    if (diffDays < 7)  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()] + ', ' + timeStr;
 33	
 34	    // Older: show short date like "12 Feb 2026, 16:41"
 35	    return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear() + ', ' + timeStr;
 36	  } catch (_) {
 37	    return escapeHtml(isoString);
 38	  }
 39	}
 40	
 41	function statusBadge(status) {
 42	  if (!status) return '';
 43	  var cls = 'badge badge-' + status.toLowerCase().replace(/_/g, '-');
 44	  return '<span class="' + cls + '">' + escapeHtml(status) + '</span>';
 45	}
 46	
 47	// Cache of namespaced key → display name, populated by views that fetch project data.
 48	// breadcrumb().project() reads from here automatically.
 49	// The cache key is the composite `repo + '/' + slug` to prevent collisions
 50	// between same-slug projects in different repositories.
 51	var ProjectNameCache = (function () {
 52	  var _cache = {};
 53	  return {
 54	    /**
 55	     * Store a display name for a project.
 56	     * @param {string} key  - Namespaced key in the form `repo/slug` (or bare slug for legacy callers).
 57	     * @param {string} name - Display name to cache.
 58	     */
 59	    set: function (key, name) {
 60	      if (key && name && name.trim()) _cache[key] = name.trim();
 61	    },
 62	    /**
 63	     * Retrieve the display name for a project.
 64	     * @param {string} key - Namespaced key in the form `repo/slug` (or bare slug for legacy callers).
 65	     * @returns {string} Cached display name, or the slug portion of the key if not found.
 66	     */
 67	    get: function (key) {
 68	      if (_cache[key]) return _cache[key];
 69	      // Fall back to the slug portion (after the last '/') so breadcrumbs show
 70	      // a readable label even before the project data is fetched.
 71	      var lastSlash = key ? key.lastIndexOf('/') : -1;
 72	      return lastSlash >= 0 ? key.slice(lastSlash + 1) : key;
 73	    },
 74	  };
 75	}());
 76	
 77	function breadcrumb() {
 78	  var segments = [];
 79	  var api = {
 80	    projects: function () {
 81	      segments.push({ label: 'Projects', href: '#/' });
 82	      return api;
 83	    },
 84	    project: function (repo, slug) {
 85	      segments.push({ label: ProjectNameCache.get(repo + '/' + slug), href: '#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) });
 86	      return api;
 87	    },
 88	    leaf: function (label) {
 89	      segments.push({ label: label });
 90	      return api;
 91	    },
 92	    leafSpan: function (label, id) {
 93	      segments.push({ label: label, id: id });
 94	      return api;
 95	    },
 96	    html: function () {
 97	      return '<p class="breadcrumb">' +
 98	        segments.map(function (s) {
 99	          if (s.href) return '<a href="' + s.href + '">' + escapeHtml(s.label) + '</a>';
100	          if (s.id)   return '<span id="' + escapeHtml(s.id) + '">' + escapeHtml(s.label) + '</span>';
101	          return escapeHtml(s.label);
102	        }).join(' / ') +
103	        '</p>';
104	    }
105	  };
106	  return api;
107	}
108	
109	function showLoading(container) {
110	  container.innerHTML = '<div class="loading">Loading…</div>';
111	}
112	
113	function showError(container, message) {
114	  container.innerHTML = '<div class="error-banner">' + escapeHtml(message) + '</div>';
115	}
116	
117	function formatDuration(ms) {
118	  if (ms == null || isNaN(ms) || ms < 0) return '—';
119	  if (ms < 1000) return '< 1s';
120	  var totalSec = Math.floor(ms / 1000);
121	  var hours = Math.floor(totalSec / 3600);
122	  var minutes = Math.floor((totalSec % 3600) / 60);
123	  var seconds = totalSec % 60;
124	  var parts = [];
125	  if (hours > 0) parts.push(hours + 'h');
126	  if (minutes > 0) parts.push(minutes + 'm');
127	  if (seconds > 0 && hours === 0) parts.push(seconds + 's');
128	  return parts.join(' ') || '< 1s';
129	}

  1	/* ============================================================
  2	   views/project-list.js — Project List view
  3	   Section 4a of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, escapeHtml, formatDate, statusBadge,
  5	               showLoading, showError
  6	   ============================================================ */
  7	
  8	function renderProjectList(app) {
  9	  showLoading(app);
 10	
 11	  var SORT_KEY_STORAGE = 'mcp-sort-key';
 12	  var SORT_DIR_STORAGE = 'mcp-sort-dir';
 13	  var PAGE_LIMIT_STORAGE = 'mcp-page-limit';
 14	  var STATUS_STORAGE = 'mcp-status-filter';
 15	  var RUNNER_STORAGE = 'mcp-runner-filter';
 16	
 17	  // --- Pagination / filter state (localStorage-persisted where noted) ---
 18	  var currentPage = 1;
 19	  var pageLimit = (function () {
 20	    var v = parseInt(localStorage.getItem(PAGE_LIMIT_STORAGE), 10);
 21	    return (!isNaN(v) && (v === 25 || v === 50 || v === 100)) ? v : 50;
 22	  }());
 23	  var currentStatus = localStorage.getItem(STATUS_STORAGE) || 'ACTIVE';
 24	  var currentRunner = localStorage.getItem(RUNNER_STORAGE) || '';
 25	  var currentSearch = '';
 26	  var currentSort = localStorage.getItem(SORT_KEY_STORAGE) || 'last_updated';
 27	  var currentDir = localStorage.getItem(SORT_DIR_STORAGE) || 'desc';
 28	
 29	  var lastTotalPages = 1;
 30	  var searchDebounceTimer = null;
 31	
 32	  // ── Action menu (kebab dropdown) state ──
 33	  var openMenuWrapper = null;
 34	
 35	  // Create or reuse the shared menu portal (appended once to <body>)
 36	  var menuPortal = (function () {
 37	    var el = document.getElementById('action-menu-portal');
 38	    if (!el) {
 39	      el = document.createElement('div');
 40	      el.id = 'action-menu-portal';
 41	      el.className = 'action-menu';
 42	      el.setAttribute('role', 'menu');
 43	      document.body.appendChild(el);
 44	    }
 45	    return el;
 46	  }());
 47	
 48	  function closeOpenMenu() {
 49	    menuPortal.style.display = 'none';
 50	    menuPortal.innerHTML = '';
 51	    if (openMenuWrapper) {
 52	      var trigger = openMenuWrapper.querySelector('.action-menu-btn');
 53	      if (trigger) trigger.setAttribute('aria-expanded', 'false');
 54	      openMenuWrapper = null;
 55	    }
 56	  }
 57	
 58	  // ── Runner display helpers ──
 59	
 60	  var RUNNER_LABELS = {
 61	    'vscode':       'VS Code',
 62	    'claude-code':  'Claude Code',
 63	    'orchestrator': 'Orchestrator',
 64	    'unknown':      'Unknown',
 65	  };
 66	
 67	  function runnerLabel(runner) {
 68	    return RUNNER_LABELS[runner] || (runner ? runner : '—');
 69	  }
 70	
 71	  function runnerBadge(runner) {
 72	    var safeRunner = runner && runner !== 'unknown' ? runner : 'unknown';
 73	    var label = RUNNER_LABELS[safeRunner] || (runner ? runner : 'Unknown');
 74	    return '<span class="badge badge-runner badge-runner-' + escapeHtml(safeRunner) + '">' + escapeHtml(label) + '</span>';
 75	  }
 76	
 77	  // ── Build runner filter dropdown options ──
 78	  // Only includes runner values that have at least one project (from runner_counts).
 79	  // Preserves a canonical display order; runners not in runner_counts are omitted.
 80	  // If currentRunner is set to a value absent from runner_counts (stale state),
 81	  // it is included as a zero-count entry so the user can see and clear it.
 82	
 83	  function buildRunnerOptions(runnerCounts) {
 84	    var counts = runnerCounts || {};
 85	
 86	    // Canonical ordering for display (determines option order in dropdown)
 87	    var RUNNER_ORDER = ['orchestrator', 'vscode', 'claude-code', 'unknown'];
 88	
 89	    // Collect runner values that have at least one project, in canonical order
 90	    var activeRunners = RUNNER_ORDER.filter(function (r) {
 91	      return counts[r] !== undefined && counts[r] > 0;
 92	    });
 93	
 94	    // Also include any non-canonical runner values that have projects
 95	    Object.keys(counts).forEach(function (r) {
 96	      if (counts[r] > 0 && RUNNER_ORDER.indexOf(r) === -1) {
 97	        activeRunners.push(r);
 98	      }
 99	    });
100	
101	    // If the current selection is stale (no longer in runner_counts), keep it
102	    // visible so the user can see and clear the filter, even with zero count.
103	    if (currentRunner && counts[currentRunner] === undefined) {
104	      activeRunners.push(currentRunner);
105	    }
106	
107	    // Build <option> elements: "All" first, then one per active runner
108	    var allSel = currentRunner === '' ? ' selected' : '';
109	    var html = '<option value=""' + allSel + '>All</option>';
110	
111	    activeRunners.forEach(function (r) {
112	      var label = RUNNER_LABELS[r] || r;
113	      var cnt = counts[r] !== undefined ? ' (' + counts[r] + ')' : '';
114	      var sel = r === currentRunner ? ' selected' : '';
115	      html += '<option value="' + escapeHtml(r) + '"' + sel + '>' + escapeHtml(label + cnt) + '</option>';
116	    });
117	
118	    return html;
119	  }
120	
121	  // ── Build table HTML (projects already sorted/filtered server-side) ──
122	
123	  function buildTable(projects) {
124	    if (!projects.length) {
125	      return '<p class="text-muted mt-16">No projects found.</p>';
126	    }
127	
128	    function thSort(label, key) {
129	      var isActive = currentSort === key;
130	      var cls = 'sortable' + (isActive ? ' sort-' + currentDir : '');
131	      var ariaSort = isActive ? (currentDir === 'asc' ? 'ascending' : 'descending') : 'none';
132	      return '<th class="' + cls + '" data-sort="' + key + '" aria-sort="' + ariaSort + '" tabindex="0" role="columnheader">' + label + '</th>';
133	    }
134	
135	    var rows = projects.map(function (p) {
136	      var projectName = (p.project_name != null && p.project_name !== '') ? escapeHtml(p.project_name) : escapeHtml(p.slug);
137	      if (p.repository_name) {
138	        ProjectNameCache.set(p.repository_name + '/' + p.slug, p.project_name || p.slug);
139	      }
140	      var doneCellHtml;
141	      if (p.total_work_packages > 0) {
142	        var pct = p.progress_pct != null ? p.progress_pct : 0;
143	        doneCellHtml = '<div class="progress-bar-track" title="' + pct + '%"><div class="progress-bar-fill" style="width:' + pct + '%"></div></div>';
144	      } else {
145	        doneCellHtml = '\u2014';
146	      }
147	      var wpCount = p.total_work_packages != null ? String(p.total_work_packages) : '\u2014';
148	      var repo = p.repository_name;
149	      var nameCell;
150	      if (repo) {

